/* cppi::20e5981652e4c4618e0bb71b5575aa7caf9a43d000c84caa35c941969dfc9781 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-12' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::be1505a1c79017763734e5f3a55572bf1867c04e8bb1181f3115f6bbda70bbbc */
